function parseLocalizedNumber(raw: string): number | null {
  if (typeof raw !== "string") return null;

  // Step 1: Map Arabic-Indic and Eastern Arabic digits to ASCII.
  let s = raw
    .replace(/[\u0660-\u0669]/g, (d) => String(d.charCodeAt(0) - 0x0660))
    .replace(/[\u06f0-\u06f9]/g, (d) => String(d.charCodeAt(0) - 0x06f0));

  // Step 2: Map Arabic separators to ASCII equivalents.
  // U+066B (٫) = Arabic decimal separator → dot
  // U+066C (٬) = Arabic thousands separator → remove (treat as thousands)
  // U+060C (،) = Arabic comma → comma
  s = s
    .replace(/[\u066b]/g, ".")
    .replace(/[\u066c]/g, "")
    .replace(/[\u060c]/g, ",");

  // Step 3: Strip whitespace used as thousands separators.
  s = s.replace(/[\s\u2009\u202f]/g, "");

  // Trim.
  s = s.trim();
  if (s === "" || s === "-" || s === ".") return null;

  // Step 4: Determine decimal separator.
  const lastDot = s.lastIndexOf(".");
  const lastComma = s.lastIndexOf(",");

  let decimalIdx = -1;
  let intPart = "";
  let fracPart = "";

  if (lastDot >= 0 && lastComma >= 0) {
    // Both present. The last one is the decimal separator.
    if (lastDot > lastComma) {
      // Dot is decimal, commas are thousands.
      decimalIdx = lastDot;
      intPart = s.slice(0, decimalIdx);
      fracPart = s.slice(decimalIdx + 1);
      intPart = intPart.replace(/,/g, "");
    } else {
