  } else if (lastComma >= 0) {
    // Only commas. If multiple, all are thousands.
    const commaCount = (s.match(/,/g) ?? []).length;
    if (commaCount > 1) {
      // All commas are thousands separators.
      intPart = s.replace(/,/g, "");
      fracPart = "";
    } else {
      // Single comma. Could be decimal or thousands.
      // Heuristic: if followed by exactly 3 digits at end AND preceded by 
      // 1-3 digits, treat as thousands. Otherwise decimal.
      const tail = s.slice(lastComma + 1);
      const head = s.slice(0, lastComma);
      if (tail.length === 3 && /^\d+$/.test(tail) && /^\d{1,3}$/.test(head.replace(/[^\d]/g, ""))) {
