export async function resolveImageUrl(
  storedValue: string | null | undefined,
): Promise<string | null> {
  if (!storedValue) return null;

  // Legacy rows store full URLs (from M2's getPublicUrl).
  if (storedValue.startsWith("http://") || storedValue.startsWith("https://")) {
    return storedValue;
  }

  // New rows store object paths. Generate a short-lived signed URL.
  if (!isSupabaseConfigured) return null;

  try {
    const supabase = getSupabase();
    const { data, error } = await supabase.storage
      .from(CLOSING_IMAGES_BUCKET)
      .createSignedUrl(storedValue, 300); // 5-minute expiry

    if (error || !data?.signedUrl) {
      console.error("[closings] createSignedUrl failed", error?.message);
      return null;
    }

    return data.signedUrl;
  } catch {
    return null;
  }
}
